window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-947cd85d20fa252c"]={"versions": [{"id": "FIG-947cd85d20fa252c", "releases": ["R1.3.0", "R17-10_R1.2.0", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenlayout- und Berechnungsdiagramm zur E2E-Kommunikationsabsicherung (AUTOSAR PRS E2E Protocol). Das Diagramm veranschaulicht den Datenstrom-Aufbau und den CRC-Abdeckungsbereich für das E2E-Profil 1 Variante 1C (E2E Profile 1 variant 1C).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine Bytefolge einer serialisierten Botschaft mit folgenden Elementen:</p>\n<ul class=\"fig-list\"><li><strong>Lowbyte of DataID</strong>: Extern zugeführter Parameter (unteres Byte der Daten-ID), der in die CRC-Berechnung einfließt, aber nicht zwingend im Nutzdatenpuffer übertragen wird.\n</li><li><strong>CRC</strong>: 1-Byte-Feld für die Prüfsumme (CRC8).\n</li><li>**Nibble \\*)**: Low-Nibble des High-Bytes der Daten-ID („Lownibble of high byte of Data ID“), platziert im höherwertigen bzw. ersten Nibble des Folgebytes.\n</li><li><strong>Counter</strong>: 4-Bit-Sequenzzähler (Alive-Counter), platziert im zweiten Nibble desselben Bytes.\n</li><li><strong>Sig1</strong>: Serialisierte Signalbereiche (Nutzdaten).\n</li><li><strong>Leere Bereiche / Auffüllbereiche</strong>: Unbesetzte Abschnitte sowie konstante Füllbytes (beispielhaft als <code>0xFF</code> dargestellt).\n</li><li><strong>Berechnungsformel</strong>: Textuelle Definition <code>CRC := CRC8 over (1) Data Id, (2) all serialized signal (including empty areas, excluding CRC byte itself)</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Berechnungs- und Serialisierungsablauf gliedert sich in:</p>\n<ol class=\"fig-list\"><li>Vorbereitung der Botschaftsdaten inklusive Signale (<code>Sig1</code>), Füllbereiche (<code>0xFF</code>), Counter-Nibble und dem Low-Nibble des High-Bytes der Data ID (\\*).\n</li><li>Berechnung des 8-Bit-CRC über zwei Anteile:\n<ul class=\"fig-list\"><li>Schritt (1): Berechnung über das <code>Lowbyte of DataID</code> (bzw. Einbindung der Data-ID-Konfiguration).\n</li><li>Schritt (2): Berechnung über alle serialisierten Signalbereiche einschließlich Leerräumen und Padding (<code>0xFF</code>), unter Ausschluss des CRC-Bytes selbst.\n</li></ul>\n</li><li>Platzierung des berechneten CRC-Wertes im designierten <code>CRC</code>-Byte am Beginn der serialisierten Struktur.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für Implementierungen des AUTOSAR E2E Profile 1 (Variante 1C):</p>\n<ul class=\"fig-list\"><li>Die CRC-Berechnung muss exakt die spezifizierten Byte- und Nibble-Positionen abdecken.\n</li><li>Das CRC-Byte selbst ist von der CRC-Berechnung auszunehmen (<code>excluding CRC byte itself</code>).\n</li><li>Füllbereiche und ungenutzte Segmente im serialisierten Puffer (z. B. <code>0xFF</code>) sind integraler Bestandteil der Prüfsummenberechnung.\n</li><li>Bei Variante 1C ist das Byte nach der CRC in zwei 4-Bit-Hälften unterteilt: ein Nibble trägt das untere Nibble des oberen Bytes der Daten-ID, das andere den E2E-Counter.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-98f6d2ffa7f03dce", "releases": ["R1.5.1", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenlayout- und Berechnungsdiagramm zur E2E-Kommunikationsabsicherung (AUTOSAR PRS E2E Protocol). Das Diagramm veranschaulicht den Datenstrom-Aufbau und den CRC-Abdeckungsbereich für das E2E-Profil 1 Variante 1C (E2E Profile 1 variant 1C).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine Bytefolge einer serialisierten Botschaft mit folgenden Elementen:</p>\n<ul class=\"fig-list\"><li><strong>Lowbyte of DataID</strong>: Extern zugeführter Parameter (unteres Byte der Daten-ID), der in die CRC-Berechnung einfließt, aber nicht zwingend im Nutzdatenpuffer übertragen wird.\n</li><li><strong>CRC</strong>: 1-Byte-Feld für die Prüfsumme (CRC8).\n</li><li>**Nibble \\*)**: Low-Nibble des High-Bytes der Daten-ID („Lownibble of high byte of Data ID“), platziert im höherwertigen bzw. ersten Nibble des Folgebytes.\n</li><li><strong>Counter</strong>: 4-Bit-Sequenzzähler (Alive-Counter), platziert im zweiten Nibble desselben Bytes.\n</li><li><strong>Sig1</strong>: Serialisierte Signalbereiche (Nutzdaten).\n</li><li><strong>Leere Bereiche / Auffüllbereiche</strong>: Unbesetzte Abschnitte sowie konstante Füllbytes (beispielhaft als <code>0xFF</code> dargestellt).\n</li><li><strong>Berechnungsformel</strong>: Textuelle Definition <code>CRC := CRC8 over (1) Data Id, (2) all serialized signal (including empty areas, excluding CRC byte itself)</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Berechnungs- und Serialisierungsablauf gliedert sich in:</p>\n<ol class=\"fig-list\"><li>Vorbereitung der Botschaftsdaten inklusive Signale (<code>Sig1</code>), Füllbereiche (<code>0xFF</code>), Counter-Nibble und dem Low-Nibble des High-Bytes der Data ID (\\*).\n</li><li>Berechnung des 8-Bit-CRC über zwei Anteile:\n<ul class=\"fig-list\"><li>Schritt (1): Berechnung über das <code>Lowbyte of DataID</code> (bzw. Einbindung der Data-ID-Konfiguration).\n</li><li>Schritt (2): Berechnung über alle serialisierten Signalbereiche einschließlich Leerräumen und Padding (<code>0xFF</code>), unter Ausschluss des CRC-Bytes selbst.\n</li></ul>\n</li><li>Platzierung des berechneten CRC-Wertes im designierten <code>CRC</code>-Byte am Beginn der serialisierten Struktur.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für Implementierungen des AUTOSAR E2E Profile 1 (Variante 1C):</p>\n<ul class=\"fig-list\"><li>Die CRC-Berechnung muss exakt die spezifizierten Byte- und Nibble-Positionen abdecken.\n</li><li>Das CRC-Byte selbst ist von der CRC-Berechnung auszunehmen (<code>excluding CRC byte itself</code>).\n</li><li>Füllbereiche und ungenutzte Segmente im serialisierten Puffer (z. B. <code>0xFF</code>) sind integraler Bestandteil der Prüfsummenberechnung.\n</li><li>Bei Variante 1C ist das Byte nach der CRC in zwei 4-Bit-Hälften unterteilt: ein Nibble trägt das untere Nibble des oberen Bytes der Daten-ID, das andere den E2E-Counter.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-947cd85d20fa252c", "to": "FIG-98f6d2ffa7f03dce", "fr": "R1.3.0", "tr": "R1.5.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-98f6d2ffa7f03dce", "to": "FIG-947cd85d20fa252c", "fr": "R1.5.1", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
